#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/capability_expansion_v3_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/capability_expansion.py "$BK/" 2>/dev/null || true
cp -a tests/test_capability_expansion.py "$BK/" 2>/dev/null || true

mkdir -p companyos/extensions/generated tests/generated
touch companyos/extensions/__init__.py companyos/extensions/generated/__init__.py tests/generated/__init__.py

echo "" | base64 -d > companyos/runtime/capability_expansion.py
echo "" | base64 -d > tests/test_capability_expansion_v3.py

echo "[1/6] Compile"
python -m py_compile companyos/runtime/capability_expansion.py tests/test_capability_expansion_v3.py

echo "[2/6] Path-contract tests"
python -m unittest tests.test_capability_expansion_v3 -v

echo "[3/6] Verify supervisor still references expansion service"
grep -q 'capability_expansion' companyos/runtime/service_supervisor.py
echo "SUPERVISOR_EXPANSION_REFERENCE=PASS"

echo "[4/6] Run one expansion cycle"
set +e
scripts/companyos_expandctl once | tee .companyos_runtime/capability_expansion_v3_first_cycle.json
RC=${PIPESTATUS[0]}
set -e
echo "EXPANSION_ONCE_RC=$RC"

echo "[5/6] Commit/push"
git add companyos/runtime/capability_expansion.py tests/test_capability_expansion_v3.py
git diff --cached --quiet || git commit -m "Fix autonomous capability expansion path contract"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[6/6] Restart + verify"
scripts/companyosctl restart || true
sleep 8
scripts/companyos_expandctl status || true
scripts/companyos_expandctl inventory || true
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CAPABILITY_EXPANSION_PATH_CONTRACT_V3=PASS"
